import os
import zipfile
import json
"""Creates architecture JSON structure for export.

Structure includes components, connections, containers, structure, 
canvas size, and third party modules.
"""
def archJSON():
	archJSON = {}
	for prop in ("components", "connections", "containers", "structure", "canvasSize"):
		archJSON[prop] = system.util.jsonDecode(system.util.jsonEncode(self.session.custom[prop]))

	# Determine which Third Party Modules are used by this architecture
	allTPMs = {}
	modulesRaw=system.util.jsonDecode(system.util.jsonEncode(self.custom.TPMJson))
	for x in self.session.custom.structure.configs:
		if self.session.custom.structure.configs[x]["type"] in ["standard", "edge", "panel", "cloud"]:
			gatewayTPMs = self.session.custom.structure.configs[x]["config"]["modules"]["TPM"]
			if len(gatewayTPMs) > 0:
				for tpm in gatewayTPMs:
					allTPMs[tpm["name"]] =modulesRaw[tpm["name"]]

	# Append the Third Party Modules
	archJSON["tpms"] = system.util.jsonDecode(system.util.jsonEncode(allTPMs))

	return archJSON

"""Creates an Excel (XLS) workbook with one or more pages.

If Gateways are selected for export, a 'Gateways' page is created in the 
workbook. The same applies for Modules. The workbook is returned. Expects
corresponding datasets to already be built.
"""
def createWorkbook():
	datasets = []
	sheets = []
	if selections["gateways"]["export"]:
		datasets.append(IgnitionGatewayDataset)
		sheets.append("Gateways")
	if selections["modules"]["export"]:
		datasets.append(IgnitionModuleDataset)
		sheets.append("Modules")
	return system.dataset.toExcel(True, datasets, True, sheets)

"""Searches the specified entry for Ignition Gateways.

Recursive function used to find Ignition Gateways in JSON structure. A
dictionary containing each Gateway's UUID, area path, name, and type is
returned.

Typical usage example:
	entries = search([], self.session.custom.structure.structure, '')
"""
def search(items, entry, path):
	for e in entry:
		if e["type"] == 'Container':
			# Recursively search for gateways
			if path == '':
				search(items, e["contents"], e["uuid"])
			else:
				search(items, e["contents"], path + '@' + e["uuid"])

		if e["type"] in ('standard', 'edge', 'panel', 'cloud'):
			items.append({'uuid': e["uuid"], 'path': path, 'name': e["name"], 'type': e["type"]})
	return items

"""Returns list of Third Party Modules defined within the builder.

Removes 'display', 'enabled', and 'selected' properties (if present), then
encodes remaining properties as JSON
"""
def tpms():
	modulesRaw=system.util.jsonDecode(system.util.jsonEncode(self.custom.TPMJson))
	modules=[]
	for mR in modulesRaw.keys():
		modParams=modulesRaw[mR]
		for prop in ["display", "enabled", "selected"]:
			system.perspective.print(prop)
			if str(prop) in modParams.keys():
				del modParams[str(prop)]
		modules.append(modParams)
	return system.util.jsonEncode(modules)

# Store audit log information
actionValue = ""

# Get user's export selections
selections = self.view.custom.selections

# If Gateways or Modules are to be exported, 
if selections["gateways"]["export"] or selections["modules"]["export"]:
	# Build Header array for Gateways
	if selections["gateways"]["export"]:
		IgnitionGatewayHeaders = ["Area", "Name", "Type"]
		if selections["gateways"]["selections"]["config"]["export"]:
			IgnitionGatewayHeaders.extend(["Description", "Version", "License Key", "Redundant", "Redundant License Key", "Development", "Trial"])
		if selections["gateways"]["selections"]["load"]["export"]:
			IgnitionGatewayHeaders.extend(["Devices", "Clients", "Tags", "History (Tag/Sec)", "SQL (Insert/Sec)", "Retention (Hrs)"])
		if selections["gateways"]["selections"]["resources"]["export"]:
			IgnitionGatewayHeaders.extend(["ARM", "Cores", "Frequency (GHz)", "RAM (GB)", "Storage (GB)", "OS Family", "OS Version"])
		IgnitionGatewayData = []

	# Build Header array for Modules
	if selections["modules"]["export"]:
		IgnitionModuleHeaders = ["Area", "Name", "Type", "Module", "Selection", "Price", "Link"]
		IgnitionModuleData = []

	# Iterate over list of Ignition Gateways
	entries = search([], self.session.custom.structure.structure, '')
	for entry in entries:
		if len(entry["path"]) > 0:
			# Build Area string
			area = []
			for node in entry["path"].split('@'):
				area.append(self.session.custom.structure.configs[node]["name"])
			areaString = "/".join(area)
		else:
			areaString = ""

		if selections["gateways"]["export"]:
			# Add record per Ignition Gateway
			if any([selections["gateways"]["selections"][i]["export"] for i in selections["gateways"]["selections"]]):
				# Get Gateway Details
				config = self.session.custom.structure.configs[entry["uuid"]]["config"]
				temp = [areaString, entry["name"], entry["type"]]
				if selections["gateways"]["selections"]["config"]["export"]:
					temp.append(self.session.custom.structure.configs[entry["uuid"]]["desc"])
					for key in ["version", "licenseKey", "redundant", "licenseKeyRedun", "development", "trial"]:
						temp.append(config[key])
				if selections["gateways"]["selections"]["load"]["export"]:
					if 'load' in config.keys():
						for key in ["devices", "clients", "tags", "histTags", "histSQL", "histHrs"]:
							temp.append(config["load"][key])
					else:
						temp.extend([0, 0, 0, 0, 0, 0])
				if selections["gateways"]["selections"]["resources"]["export"]:
					if 'resources' in config.keys():
						for key in ["arm", "cores", "frequency"]:
							temp.append(config["resources"]["cpu"][key])
						for key in ["disk", "ram"]:
							temp.append(config["resources"][key]["capacity"])
						for key in ["type", "version"]:
							temp.append(config["resources"]["os"][key])
					else:
						temp.extend([False, 2, 2, 10, 4, "N/A", "N/A"])
			IgnitionGatewayData.append(temp)

		if selections["modules"]["export"]:
			# Add record per Module per Ignition Gateway
			modules = self.session.custom.structure.configs[entry["uuid"]]["config"]["modules"]
			for author in modules:
				if len(modules[author]) > 0:
					for module in modules[author]:
						temp = [areaString, entry["name"], entry["type"], module["name"]]

						# Append module selection (default empty string)
						selection = None
						if 'selection' in module.keys():
							selection = module["selection"]
						temp.append(selection or '')

						# Append module price
						if self.session.custom.structure.configs[entry["uuid"]]["config"]["trial"]:
							retailPrice = 0
						else:
							retailPrice = exchange.architecturebuilder.modules.getRetail(author, module["name"], selection=selection, gwType=entry["type"])
						temp.append(str(retailPrice))

						# Append module link (default empty string)
						link = ''
						if 'link' in module.keys():
							link = module["link"]
						temp.append(link)

						# Append module details
						IgnitionModuleData.append(temp)

	# Create datasets
	if selections["gateways"]["export"]:
		IgnitionGatewayDataset = system.dataset.toDataSet(IgnitionGatewayHeaders, IgnitionGatewayData)
	if selections["modules"]["export"]:
		system.perspective.print(IgnitionModuleHeaders)						########## CLEANUP
		system.perspective.print(IgnitionModuleData)						########## CLEANUP
		IgnitionModuleDataset = system.dataset.toDataSet(IgnitionModuleHeaders, IgnitionModuleData)

# File properties
filePrefix = self.parent.parent.getChild("Filename").getChild("TextField").props.text
fileExtension = self.parent.parent.getChild("Settings").getChild("BOM").getChild("Selections").getChild("FileFormat").getChild("RadioGroup").props.value

# Export single file
if fileExtension.lower() == 'xls' and not (selections["architecture"]["export"] or selections["thirdPartyModules"]["export"]):
	filename = filePrefix + ' BOM.xls'
	actionValue = filename
	# Export single Excel Workbook
	system.perspective.download(filename, createWorkbook())
elif sum([selections[i]["export"] for i in selections]) == 1:
	# Export single file containing Gateway information
	if selections["gateways"]["export"]:
		if fileExtension.lower() == 'csv':
			IgnitionGatewayCSV = system.dataset.toCSV(IgnitionGatewayDataset, True, False, True)
			filename = filePrefix + ' Ignition Gateway BOM.csv'
			actionValue = filename
			system.perspective.download(filename, IgnitionGatewayCSV)
		elif fileExtension.lower() == 'xls':
			IgnitionGatewayXLS = system.dataset.toExcel(True, [IgnitionGatewayDataset], True, ["Gateways"])
			filename = filePrefix + ' Ignition Gateway BOM.xls'
			actionValue = filename
			system.perspective.download(filename, IgnitionGatewayXLS)
		else:
			system.perspective.print("Invalid File Format '%'" % fileExtension)

	# Export single file containing Module information
	elif selections["modules"]["export"]:
		if fileExtension.lower() == 'csv':
			IgnitionModuleCSV = system.dataset.toCSV(IgnitionModuleDataset, True, False, True)
			filename = filePrefix + ' Ignition Modules BOM.csv'
			actionValue = filename
			system.perspective.download(filename, IgnitionModuleCSV)
		elif fileExtension.lower() == 'xls':
			IgnitionModuleXLS = system.dataset.toExcel(True, [IgnitionModuleDataset], True, ["Gateways"])
			filename = filePrefix + ' Ignition Module BOM.xls'
			actionValue = filename
			system.perspective.download(filename, IgnitionModuleXLS)
		else:
			system.perspective.print("Invalid File Format '%'" % fileExtension)

	# Export single file containing Architecture (JSON)
	elif selections["architecture"]["export"]:
		filename = filePrefix + " Architecture.json"
		actionValue = filename
		system.perspective.download(filename, system.util.jsonEncode(archJSON()))

	# Export single file containing all Third Party Modules
	elif selections["thirdPartyModules"]["export"]:
		filename = filePrefix + " Third Party Modules.json"
		actionValue = filename
		system.perspective.download(filename, tpms())

	else:
		system.perspective.print("Invalid Export Selection")

# ZIP multiple files selected for export
else:
	filenames = []
	tempZip = system.file.getTempFile("zip")
	with zipfile.ZipFile(tempZip, 'w', zipfile.ZIP_DEFLATED) as zipf:
		if selections["gateways"]["export"] or selections["modules"]["export"]:
			if fileExtension.lower() == 'xls':
				# Zip single Excel Workbook and Architecture.JSON
				tempWorkbook = system.file.getTempFile("xls")
				system.file.writeFile(tempWorkbook, createWorkbook())
				filename = filePrefix + ' BOM.xls'
				filenames.append(filename)
				zipf.write(tempWorkbook, arcname = filename)
			elif fileExtension.lower() == 'csv':
				if selections["gateways"]["export"]:
					tempIgnitionGateway = system.file.getTempFile("csv")
					system.file.writeFile(tempIgnitionGateway, system.dataset.toCSV(IgnitionGatewayDataset, True, False, True))
					filename = filePrefix + ' Ignition Gateway BOM.csv'
					filenames.append(filename)
					zipf.write(tempIgnitionGateway, arcname = filename) 
				if selections["modules"]["export"]:
					tempModule = system.file.getTempFile("csv")
					system.file.writeFile(tempModule, system.dataset.toCSV(IgnitionModuleDataset, True, False, True))
					filename = filePrefix + ' Ignition Modules BOM.csv'
					filenames.append(filename)
					zipf.write(tempModule, arcname = filename)
		if selections["architecture"]["export"]:
			tempArch = system.file.getTempFile("json")
			system.file.writeFile(tempArch, system.util.jsonEncode(archJSON()))
			filename = filePrefix + ' Architecture.json'
			filenames.append(filename)
			zipf.write(tempArch, arcname = filename)
		if selections["thirdPartyModules"]["export"]:
			tempTPMs = system.file.getTempFile("json")
			system.file.writeFile(tempTPMs, tpms())
			filename = filePrefix + ' Third Party Modules.json'
			filenames.append(filename)
			zipf.write(tempTPMs, arcname = filename)
	zipf.close()
	system.perspective.download(filePrefix + ' BOM.zip', system.file.readFileAsBytes(tempZip))
	actionValue = "Zip: " + ','.join(filenames)

# Log Download event
if self.session.custom.audit.global:
	system.util.audit(action="Downloaded", actionTarget="Exports", actionValue=actionValue)
